window.CA = {"date": "Tuesday, 14 July 2026", "updated": "2026-07-14 02:00", "updated_label": "14 Jul 2026, 02:00 IST", "items": [{"title": "US-Iran Conflict: US Reinstates Maritime Blockade on Iran; Strikes Iranian Submarine Centre Using Sea Drones", "category": "ir", "category_name": "International Relations", "summary": "The United States reinstated a maritime blockade on Iran amid escalating military conflict, with US forces conducting strikes on Iran including, for the first time, an attack on an Iranian submarine centre using sea drones. Iran retaliated by targeting vessels in the Strait of Hormuz and hitting Gulf nations. President Trump also demanded a 20% fee for US protection of shipping in the Strait of Hormuz, which Iran called excessive.", "exam_angle": "The Strait of Hormuz is a critical global oil chokepoint; US-Iran tensions directly impact India's energy security, trade routes, and crude oil imports. Relevant for GS Paper 2 (International Relations) and GS Paper 3 (Energy Security).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["US reinstated maritime blockade on Iran and struck Iranian submarine centre using sea drones", "Strait of Hormuz: ~20% of global oil trade passes through it; critical for India's energy imports", "Trump demanded 20% fee for US protection of shipping in Hormuz", "Iran retaliated by targeting vessels in the Strait of Hormuz"], "source": "The Hindu / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Trade Deficit Widens to Five-Month High of $30.43 Billion in June 2026 Amid Hormuz Disruptions", "category": "economy", "category_name": "Economy & Banking", "summary": "India's merchandise trade deficit widened to a five-month high of $30.43 billion in June 2026, a jump of approximately 430% year-on-year, driven by surging imports of oil, gold, and electronics amid disruptions in the Strait of Hormuz. The US-Iran conflict has added risk to India's import-heavy trade outlook. Weak exports also contributed to the widening deficit.", "exam_angle": "India's trade deficit trends are key data points for GS Paper 3 (Economy); the Hormuz disruption illustrates the vulnerability of India's import-dependent economy to geopolitical shocks.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Trade deficit: $30.43 billion in June 2026 (five-month high)", "Deficit jumped ~430% year-on-year in June 2026", "Key drivers: surging oil, gold, and electronics imports", "Hormuz disruptions cited as a major risk factor for India's trade outlook"], "source": "Business Standard / The Hindu / Reuters", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India-US Trade Deal Framework 'Ready'; Agriculture and Comparative Advantage Still Under Negotiation", "category": "ir", "category_name": "International Relations", "summary": "India's Commerce Secretary stated that the framework for an India-US bilateral trade deal is ready but certain aspects, particularly comparative advantage and agriculture, are still being worked out. Commerce Minister Piyush Goyal rejected reports that India was holding out on the deal. The US Ambassador also denied reports that India had rejected a quick deal, calling them 'fake news'.", "exam_angle": "India-US trade negotiations are a recurring theme in GS Paper 2 (IR) and GS Paper 3 (Economy); key issues include tariffs, agriculture market access, and intellectual property — all potential exam topics.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-US trade deal framework described as 'ready' by Commerce Secretary", "India firm on not ceding ground on agriculture in trade talks", "Comparative advantage clauses still under negotiation", "Commerce Minister Piyush Goyal denied India is holding back on the deal"], "source": "The Hindu / Reuters / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Ladakh to Get UT-Level Governance Body and Hill Councils for All Seven Districts Under Customised Article 371 Framework", "category": "polity", "category_name": "Polity & Governance", "summary": "The Central Government announced that Ladakh will receive a Union Territory-level governance body along with Autonomous Hill Councils extended to all seven districts, under a framework described as a 'customised Article 371 arrangement'. Currently, hill councils exist only in Leh and Kargil districts. Ladakh also created 17 new tehsils to improve administrative access for citizens.", "exam_angle": "This is directly relevant to GS Paper 2 (Polity) — Article 371 special provisions, the status of Ladakh as a UT without legislature (post-Article 370 abrogation), and the demand for statehood/legislature by Ladakh.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Ladakh to get a UT-level governance body and hill councils in all 7 districts", "Framework described as 'customised Article 371 arrangement'", "Currently hill councils exist only in Leh and Kargil districts", "17 new tehsils created in Ladakh to improve administrative access"], "source": "Hindustan Times / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Supreme Court Seeks Centre's New Aviation Rules to Regulate Airfare Volatility Within Two Weeks", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court directed the Central Government to place on record new aviation rules aimed at regulating volatile airfares within two weeks, accepting them in a sealed cover. The court expressed concern over 'unpredictable fluctuations' in domestic airfares. The Ministry of Civil Aviation is expected to submit the regulatory framework being devised.", "exam_angle": "Supreme Court interventions in economic regulation are relevant for GS Paper 2 (Polity/Judiciary); also connects to consumer protection rights under Article 21 and the regulatory role of DGCA.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Supreme Court asked Centre to submit new aviation airfare regulation rules within 2 weeks", "Rules to be submitted in sealed cover", "Issue: 'unpredictable fluctuations' in domestic airfares", "Regulatory body for civil aviation: DGCA (Directorate General of Civil Aviation)"], "source": "The Hindu / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "UK Bans Iran's Islamic Revolutionary Guard Corps (IRGC), Links IRGC-Backed Group to Attacks on Jewish Community", "category": "ir", "category_name": "International Relations", "summary": "The United Kingdom formally banned Iran's Islamic Revolutionary Guard Corps (IRGC), designating it as a terrorist organisation and holding an IRGC-backed group responsible for attacks on the Jewish community in the UK. The move aligns the UK with the US and EU positions on the IRGC. The ban makes membership in or support of the IRGC a criminal offence in the UK.", "exam_angle": "IRGC proscription is significant for GS Paper 2 (IR) — it reflects the broader Western response to Iran's regional activities and has implications for multilateral sanctions regimes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["UK formally banned Iran's IRGC, designating it a terrorist organisation", "IRGC-backed group linked to attacks on UK's Jewish community", "Membership or support of IRGC now a criminal offence in the UK", "US has designated IRGC as a Foreign Terrorist Organization since 2019"], "source": "BBC / The Times of India", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "PM Modi to Launch India's First Hydrogen-Powered Train on July 17 During Haryana Visit", "category": "scitech", "category_name": "Science & Technology", "summary": "Prime Minister Narendra Modi is scheduled to launch India's first hydrogen-powered train during his visit to Haryana on July 17, 2026. The train represents a significant step in India's green hydrogen mission and railway decarbonisation efforts. Indian Railways has been piloting hydrogen fuel cell technology as part of its net-zero 2030 target.", "exam_angle": "India's first hydrogen-powered train connects to GS Paper 3 (Sci-Tech / Environment) — Green Hydrogen Mission, railway decarbonisation, and India's net-zero targets are high-priority exam topics.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["India's first hydrogen-powered train to be launched by PM Modi on July 17, 2026", "Launch location: Haryana", "Connects to India's National Green Hydrogen Mission", "Indian Railways' target: Net Zero Carbon Emissions by 2030"], "source": "The New Indian Express", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Aditya Birla Group to Acquire Shell's Sprng Energy for $1.8 Billion in Major Renewables Deal", "category": "economy", "category_name": "Economy & Banking", "summary": "Aditya Birla Group announced the acquisition of Sprng Energy, Shell's India-based renewable energy arm, for approximately $1.8 billion (around ₹17,200 crore). Sprng Energy has a significant portfolio of solar and wind energy assets in India. The deal marks one of the largest renewable energy acquisitions in India and strengthens Aditya Birla Group's position in the clean energy sector.", "exam_angle": "Large-scale renewable energy M&A activity is relevant for GS Paper 3 (Economy/Environment) — highlights private sector role in India's energy transition and the 500 GW non-fossil fuel target by 2030.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Aditya Birla Group acquires Sprng Energy from Shell for $1.8 billion (~₹17,200 crore)", "Sprng Energy is Shell's India-based renewable energy arm", "One of the largest renewable energy acquisitions in India", "Connects to India's target of 500 GW renewable energy capacity by 2030"], "source": "Moneycontrol / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "MeitY Releases 2nd Edition of Digital Threat Report 2025-26 for India's BFSI Sector", "category": "reports", "category_name": "Reports & Indices", "summary": "The Ministry of Electronics and Information Technology (MeitY) released the second edition of the Digital Threat Report 2025-26 for India's Banking, Financial Services, and Insurance (BFSI) sector, in collaboration with SISA. The report flagged that six of seven cyber threats identified in the previous year have now become operational. The BFSI sector is identified as the most targeted sector for cyberattacks in India.", "exam_angle": "Cybersecurity reports from MeitY are relevant for GS Paper 3 (Sci-Tech/Internal Security); the BFSI sector's cyber vulnerability connects to critical infrastructure protection — a common exam theme.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Report: MeitY's Digital Threat Report 2025-26, 2nd edition for India's BFSI sector", "Released in collaboration with SISA", "6 of 7 cyber threats flagged last year are now operational", "BFSI sector is India's most targeted sector for cyberattacks"], "source": "PIB / The Times of India", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Tahir Hussain Convicted for Murder of IB Officer Ankit Sharma During 2020 Delhi Riots", "category": "polity", "category_name": "Polity & Governance", "summary": "Former AAP leader Tahir Hussain has been convicted by a Delhi court for the murder of Intelligence Bureau (IB) officer Ankit Sharma during the February 2020 Northeast Delhi riots. Hussain was accused of orchestrating mob violence from his residence. The case was one of the most prominent arising from the Delhi riots, which resulted in over 50 deaths.", "exam_angle": "Relevant for GS Paper 2 (Polity/Governance) and GS Paper 3 (Internal Security) — the Delhi riots case involved communal violence, law enforcement, and the role of elected representatives in incitement.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Tahir Hussain (former AAP leader) convicted for murder of IB officer Ankit Sharma", "Crime took place during February 2020 Northeast Delhi riots", "Delhi riots resulted in 53+ deaths", "Hussain was arrested in 2020; case investigated by Delhi Police Special Cell"], "source": "NDTV / India Today / Hindustan Times", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Jharkhand Police Arrest Top Maoist Leader Ravindra Ganjhu in Major Anti-Naxal Operation", "category": "defence", "category_name": "Defence & Security", "summary": "Jharkhand Police arrested top Maoist leader Ravindra Ganjhu in a major anti-Naxal breakthrough. Ganjhu is described as a senior commander in the CPI (Maoist) organisation. The arrest is seen as a significant blow to Left Wing Extremism (LWE) activities in Jharkhand, one of the most affected states in India's Red Corridor.", "exam_angle": "Left Wing Extremism (Naxalism) is a key internal security topic for GS Paper 3; arrests of top leadership are used by the government to showcase progress in its anti-Naxal strategy.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Arrested: Ravindra Ganjhu, top Maoist/CPI(Maoist) leader", "Arrested by: Jharkhand Police", "Jharkhand is part of India's LWE-affected 'Red Corridor'", "Government aims to eliminate LWE by 2026 under its security grid approach"], "source": "The New Indian Express", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Dhruva Space Secures First Investment from India's Antariksh Venture Fund", "category": "scitech", "category_name": "Science & Technology", "summary": "Hyderabad-based Dhruva Space has secured the first investment from India's Antariksh Venture Fund, a government-backed fund-of-funds established to promote the private space ecosystem. This marks the inaugural deployment of the Antariksh Fund, which was set up under the Indian National Space Promotion and Authorisation Centre (IN-SPACe) framework. Dhruva Space is a leading private space startup in India focused on satellite integration and launch services.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech) — India's space sector reforms including IN-SPACe, the Antariksh Fund, and the role of private players like Dhruva Space are frequently examined topics.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Dhruva Space: first company to receive investment from India's Antariksh Venture Fund", "Antariksh Fund: government-backed fund-of-funds for private space sector under IN-SPACe", "Dhruva Space is based in Hyderabad; focuses on satellite integration and launch services", "IN-SPACe (Indian National Space Promotion and Authorisation Centre) regulates and promotes private space activity in India"], "source": "Analytics India Magazine", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "DRI Busts Multiple Wildlife Trafficking Networks Across India", "category": "environment", "category_name": "Environment & Ecology", "summary": "The Directorate of Revenue Intelligence (DRI) dismantled several wildlife trafficking networks operating across India in a coordinated enforcement operation. The operations resulted in seizures of protected wildlife species and arrests of key traffickers. Wildlife trafficking is a major concern under the Wildlife Protection Act, 1972 and CITES (Convention on International Trade in Endangered Species).", "exam_angle": "Wildlife crime enforcement is relevant for GS Paper 3 (Environment); DRI's role, CITES obligations, and India's legal framework under the Wildlife Protection Act are standard exam topics.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Agency: Directorate of Revenue Intelligence (DRI) busted multiple wildlife trafficking networks", "Key legislation: Wildlife Protection Act, 1972", "India is a signatory to CITES (Convention on International Trade in Endangered Species)", "Wildlife trafficking is a Schedule 1 offence under the Wildlife Protection Act"], "source": "PIB", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Ukraine and Nine Nations Form Coalition Against Ballistic Missiles to Protect Europe", "category": "ir", "category_name": "International Relations", "summary": "Ukraine and nine other countries have formed a multilateral coalition aimed at countering ballistic missile threats to European security. The coalition focuses on air defence sharing, intelligence cooperation, and joint procurement of missile defence systems. This development comes amid ongoing Russian missile strikes on Ukraine and growing concern about missile proliferation in Europe.", "exam_angle": "Multilateral security coalitions are relevant for GS Paper 2 (IR) — NATO, collective security mechanisms, and European security architecture are recurring themes in UPSC.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Ukraine + 9 nations formed a coalition against ballistic missile threats in Europe", "Focus areas: air defence sharing, intelligence cooperation, joint missile defence procurement", "Context: Ongoing Russia-Ukraine war with sustained Russian ballistic missile attacks", "Connects to debates on collective security, NATO Article 5, and European defence architecture"], "source": "Business Standard / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Trump Moves to Dismantle International Criminal Court, Calling It 'Intolerable Threat to US Sovereignty'", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump announced moves to dismantle the International Criminal Court (ICC), describing it as an 'intolerable threat to US sovereignty.' The US has previously withdrawn from ICC jurisdiction and sanctioned ICC officials. The ICC, based in The Hague, operates under the Rome Statute and has jurisdiction over genocide, crimes against humanity, war crimes, and crimes of aggression.", "exam_angle": "The ICC and the Rome Statute are standard GS Paper 2 (IR) topics; US non-membership in the ICC and its opposition to the court is a key point for international institutions questions.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["ICC (International Criminal Court) established under Rome Statute, 1998; operational from 2002", "Headquartered in The Hague, Netherlands", "USA has never ratified the Rome Statute and is not an ICC member", "ICC has jurisdiction over genocide, crimes against humanity, war crimes, and crimes of aggression"], "source": "The Times of India", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Bharat Tex 2026: India Prepares to Host World's Largest Global Textiles Expo", "category": "economy", "category_name": "Economy & Banking", "summary": "India is preparing to host Bharat Tex 2026, described as the world's largest global textiles expo. Union Minister of Textiles Giriraj Singh also visited 'Indie Haat 2026' at the National Crafts Museum, New Delhi, and the 'Weave the Future 4.0' exhibition, highlighting India's rich craft traditions. Bharat Tex is a flagship initiative of the Ministry of Textiles to showcase India's textile ecosystem globally.", "exam_angle": "Bharat Tex and India's textiles export promotion are relevant for GS Paper 3 (Economy) — the textile sector is one of India's largest employment generators and a key export sector.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Bharat Tex 2026: described as world's largest global textiles expo", "Organised by: Ministry of Textiles, Government of India", "Union Textiles Minister: Giriraj Singh", "India's textile sector is 2nd largest employment generator after agriculture"], "source": "PIB", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Poland Acknowledges PM Modi's Key Diplomatic Role in Russia-Ukraine Conflict", "category": "ir", "category_name": "International Relations", "summary": "A top Polish official stated that 'Putin pays attention to what PM Modi says,' acknowledging India's significant diplomatic influence in mediating or influencing the Russia-Ukraine conflict. Poland, a frontline NATO state, signalled appreciation for India's engagement with Russia as a potential channel for peace. PM Modi had previously visited both Moscow and Kyiv, urging dialogue.", "exam_angle": "India's strategic autonomy, its role in the Russia-Ukraine conflict, and PM Modi's diplomatic outreach are high-priority GS Paper 2 (IR) topics; India's position as a voice of the Global South is also relevant.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Polish official: 'Putin pays attention to what PM Modi says'", "PM Modi has visited both Moscow (July 2024) and Kyiv (August 2024)", "India has maintained strategic autonomy — not joining Western sanctions on Russia", "India is a major importer of Russian oil since 2022, with discounted crude"], "source": "The Times of India", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Oil Companies Plan to Expand Sales of 10-kg LPG Cylinders", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "State-owned oil companies are planning to expand the sales network for 10-kg LPG cylinders, aimed at offering a more affordable and accessible option compared to the standard 14.2-kg domestic cylinder. The initiative is targeted at lower-income households and small commercial users. The move is expected to complement schemes like PM Ujjwala Yojana by improving LPG penetration.", "exam_angle": "LPG distribution policy connects to GS Paper 2 (Government Schemes) — PM Ujjwala Yojana, LPG subsidies, and clean cooking fuel access are standard exam topics.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Oil PSUs plan expansion of 10-kg LPG cylinder sales across India", "10-kg cylinder is more affordable than standard 14.2-kg domestic cylinder", "Relevant government scheme: PM Ujjwala Yojana (free LPG connections to BPL households)", "India is the 2nd largest LPG consumer in the world"], "source": "The Times of India", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Theatre Command Plan Nears Approval After Two Decades", "category": "defence", "category_name": "Defence & Security", "summary": "Chief of Defence Staff General Anil Chauhan (referred to as CDS Subramani in some reports) is set to seek formal approval for India's theatre commands from Defence Minister Rajnath Singh, marking a landmark moment in military reform. Theatrisation refers to the integration of Army, Navy, and Air Force assets under unified geographic commands for synergised operations. The plan has been in deliberation for over 20 years and is India's most significant military restructuring since independence. The approval would lead to the creation of joint theatre commands, replacing the current single-service command structure.", "exam_angle": "Theatrisation is a core topic under GS Paper 3 (Internal Security & Defence); questions frequently appear on the role of CDS, jointness in armed forces, and defence reforms post-Kargil Review Committee.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Theatre commands integrate Army, Navy, and Air Force under unified geographic commands", "Approval to be sought from Defence Minister Rajnath Singh", "CDS is the nodal authority for promoting jointness and theatrisation", "Reform has been under discussion for over 20 years; recommended post-Kargil Review Committee (1999)"], "source": "NDTV / Hindustan Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India-Australia Administrative Arrangements for Uranium Supplies Signed", "category": "ir", "category_name": "International Relations", "summary": "During PM Narendra Modi's visit to Australia, both countries signed administrative arrangements for uranium supplies to India, strengthening the civil nuclear cooperation framework established under the 2014 India-Australia Civil Nuclear Cooperation Agreement. PM Modi gifted Australian PM Anthony Albanese premium coffee and a Colonial Cousins vinyl album. The uranium supply arrangements are significant for India's nuclear energy programme and energy security goals.", "exam_angle": "India's civil nuclear agreements and uranium supply arrangements are important for GS Paper 2 (IR) — connects to India's nuclear energy policy, NSG waiver (2008), and bilateral energy diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Australia Civil Nuclear Cooperation Agreement originally signed in 2014", "Administrative arrangements for uranium supplies formalised during PM Modi's Australia visit", "Australia is among the world's largest uranium producers", "India requires uranium imports for its civilian nuclear power programme"], "source": "NDTV / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Maharashtra's Ladki Bahin Scheme: 92 Lakh Beneficiaries Removed After Verification; CAG Flags Rs 3,541 Crore Excess Spend", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Maharashtra's Ladki Bahin Yojana, a scheme providing monthly financial assistance to women, saw approximately 92 lakh (nearly 4 in 10) beneficiaries dropped following a verification drive. The Comptroller and Auditor General (CAG) flagged Rs 3,541 crore in excess expenditure and budgetary lapses in the scheme's implementation. The scheme had been a major electoral promise before the 2024 Maharashtra Assembly elections. The large-scale removal of beneficiaries raises questions about initial enrolment processes and fiscal management.", "exam_angle": "Connects to GS Paper 2 (Governance) — Direct Benefit Transfer, welfare scheme implementation, CAG's role as constitutional auditor (Article 148), and fiscal federalism issues.", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Ladki Bahin Yojana: monthly cash transfer scheme for women in Maharashtra", "92 lakh beneficiaries (nearly 40%) removed after verification", "CAG flagged Rs 3,541 crore excess expenditure and budgetary lapses", "CAG is a constitutional body under Article 148 of the Constitution"], "source": "Moneycontrol / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India Declares One-Day National Mourning for Former Qatar Emir Sheikh Hamad Al Thani", "category": "ir", "category_name": "International Relations", "summary": "India declared one day of national mourning following the death of former Emir of Qatar, Sheikh Hamad bin Khalifa Al Thani. Qatar is a strategically important partner for India, being a major source of LNG imports and home to a large Indian diaspora. The gesture reflects the depth of India-Qatar bilateral ties. Sheikh Hamad had ruled Qatar from 1995 to 2013 before abdicating in favour of his son, Sheikh Tamim bin Hamad Al Thani.", "exam_angle": "India-Qatar relations are relevant for GS Paper 2 (IR) — energy diplomacy, diaspora, Gulf Cooperation Council (GCC) engagement, and India's LNG import dependency.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Former Emir Sheikh Hamad bin Khalifa Al Thani ruled Qatar from 1995–2013", "India declared one day of national mourning", "Qatar is a major supplier of LNG to India", "Large Indian diaspora resides in Qatar; bilateral ties include energy, trade, and labour"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "US-Iran Military Strikes Escalate; Oil Prices Jump 4%, Rupee Slips 39 Paise", "category": "economy", "category_name": "Economy & Banking", "summary": "The United States launched a new wave of airstrikes against Iran after Tehran declared diplomacy had proven 'futile' following the death of Supreme Leader Khamenei. The escalation pushed global oil prices up by 4%, triggering concerns about the Strait of Hormuz and energy supply disruptions. Consequently, the Indian rupee slipped 39 paise against the US dollar, reflecting pressure on India's current account given its heavy oil import dependency. India's trade deficit also widened as Hormuz uncertainty clouded the outlook.", "exam_angle": "Connects to GS Paper 3 (Economy) — oil price impact on India's macroeconomics, current account deficit, exchange rate management by RBI, and geopolitical risk to energy security.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["US launched new airstrikes against Iran; Tehran declared diplomacy 'futile'", "Global oil prices rose approximately 4%", "Indian rupee fell 39 paise against US dollar", "Strait of Hormuz: critical chokepoint through which ~20% of global oil trade passes"], "source": "The Times of India / Bloomberg / The Guardian", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India-US Trade Deal Talks: India Refuses Rush, Holds Firm on Agriculture", "category": "ir", "category_name": "International Relations", "summary": "India's Trade Secretary stated that India is progressing on a trade deal with the US but sees no major challenges, while simultaneously reports indicated India is refusing a rushed agreement and will not cede ground on agriculture. India is seeking tariff advantages before finalising any deal. The negotiations come amid the US applying reciprocal tariffs on Indian goods, and India prioritising national interests in sectors like dairy and agriculture.", "exam_angle": "India-US bilateral trade negotiations are key for GS Paper 2 (IR) and GS Paper 3 (Economy); connects to WTO obligations, agriculture subsidies, and India's trade policy stance.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India's Trade Secretary confirmed progress on India-US trade deal", "India refusing to cede ground on agriculture sector in trade negotiations", "India seeking tariff advantages before signing", "Context: US imposed reciprocal tariffs; India is among the top US trading partners"], "source": "Reuters / Times of India / Firstpost", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Bharat Tex 2026: India to Host World's Largest Global Textiles Expo", "category": "economy", "category_name": "Economy & Banking", "summary": "India is preparing to host Bharat Tex 2026, described as the world's largest global textiles expo. The event is organised to showcase India's textile sector, attract global buyers and investors, and reinforce India's position as a global textile hub. The PIB announcement highlights the government's focus on promoting the textile industry as a key driver of exports and employment. India is among the world's largest textile and apparel exporters.", "exam_angle": "Relevant for GS Paper 3 (Economy) — India's textile industry, export promotion, Make in India, and schemes like PM MITRA (Mega Integrated Textile Region and Apparel) Parks.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Bharat Tex 2026: billed as the world's largest global textiles expo", "Organised by India to showcase textile sector capabilities", "India is among the world's top 5 textile and apparel exporters", "Connects to PM MITRA scheme and National Textile Policy"], "source": "PIB", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Supreme Court Releases Draft Report on Use of Artificial Intelligence in Courtrooms", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India released a draft report on the use of Artificial Intelligence (AI) in courtrooms, examining how AI tools can assist in judicial processes including case management, legal research, and transcription. The report is part of the judiciary's effort to modernise court infrastructure and reduce pendency. It raises important questions about data privacy, algorithmic bias, and accountability in judicial decision-making. The Supreme Court has previously launched the SUPACE (Supreme Court Portal for Assistance in Court's Efficiency) AI tool.", "exam_angle": "Relevant for GS Paper 2 (Polity/Governance) — judicial reforms, technology in governance, and GS Paper 3 (Sci-Tech) — AI regulation and ethics; SUPACE is a frequently asked fact.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Supreme Court released draft report on AI use in courtrooms", "SUPACE: AI tool previously launched by Supreme Court for judicial efficiency", "Report addresses data privacy, algorithmic bias, and judicial accountability", "Judiciary aims to use AI to reduce case pendency (over 5 crore cases pending in India)"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Karnataka Governor Suspends KPSC Chairman Over Illegal Appointments of Daughters", "category": "polity", "category_name": "Polity & Governance", "summary": "The Governor of Karnataka suspended the Karnataka Public Service Commission (KPSC) Chairman following a controversy over the illegal appointment of his daughters. The KPSC is a constitutional body responsible for recruitment to state civil services under Article 315 of the Constitution. The Governor exercised powers to suspend the chairman pending inquiry into the alleged nepotism and irregularities in appointments.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — constitutional bodies, role of Public Service Commissions (Article 315–323), Governor's powers, and issues of accountability in recruitment bodies.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["KPSC: Karnataka Public Service Commission, constituted under Article 315 of the Constitution", "Chairman suspended by Karnataka Governor for illegally appointing his daughters", "PSC members can be removed only by the President/Governor after Supreme Court/High Court inquiry (Article 317)", "KPSC conducts recruitment to Group A & B state civil services"], "source": "Hindustan Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Two Pakistanis Arrested in Karnataka's Chikkaballapur for Obtaining Voter IDs", "category": "polity", "category_name": "Polity & Governance", "summary": "Two Pakistani nationals were arrested in Chikkaballapur, Karnataka, for allegedly obtaining Indian Voter Identity Cards fraudulently. The case raises serious concerns about illegal infiltration and document fraud, and highlights vulnerabilities in the electoral roll management process. The Election Commission of India is responsible for maintaining electoral rolls, and obtaining a Voter ID by a foreign national is an offence under the Representation of the People Act, 1950.", "exam_angle": "Relevant to GS Paper 2 (Polity) — electoral integrity, Representation of the People Act, and internal security concerns; also connects to Foreigners Act and citizenship laws.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Two Pakistani nationals arrested in Chikkaballapur, Karnataka", "Charge: fraudulently obtaining Indian Voter Identity Cards", "Offence under Representation of the People Act, 1950", "Election Commission of India is the constitutional body for electoral roll management (Article 324)"], "source": "News18", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "BrahMos Missile Completes 25 Years: India's Supersonic Cruise Missile Technology and Future Plans", "category": "defence", "category_name": "Defence & Security", "summary": "BrahMos, India's supersonic cruise missile developed jointly by India (DRDO) and Russia (NPO Mashinostroyeniya), completes 25 years of its development journey. BrahMos is the world's fastest operational supersonic cruise missile, capable of speeds up to Mach 2.8–3.0. India has been expanding BrahMos exports (Philippines being the first buyer) and developing an extended-range (450 km+) and hypersonic version (BrahMos-II/BrahMos-NG). The missile is deployed across all three services — Army, Navy, and Air Force.", "exam_angle": "BrahMos is a perennial UPSC favourite under GS Paper 3 (Sci-Tech/Defence) — covers DRDO, India-Russia defence cooperation, indigenisation, and export diplomacy.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["BrahMos: joint venture between DRDO (India) and NPO Mashinostroyeniya (Russia)", "World's fastest operational supersonic cruise missile — speed ~Mach 2.8–3.0", "First export customer: Philippines (2022 contract)", "BrahMos-NG (Next Generation) and BrahMos-II (hypersonic) under development"], "source": "The Times of India", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "MeitY Secretary Calls for Resilient Software and Hardware Systems to Counter Cyber Threats", "category": "scitech", "category_name": "Science & Technology", "summary": "The Secretary of the Ministry of Electronics and Information Technology (MeitY) emphasised the need for India to build resilient domestic software and hardware systems capable of withstanding growing cyber threats. The statement was made in the context of rising geopolitical cyber risks and India's push for technological self-reliance. The remarks align with India's National Cyber Security Policy and the Semicon India programme for domestic semiconductor manufacturing.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech and Internal Security) — cyber security policy, MeitY's role, India Semiconductor Mission, and digital sovereignty.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["MeitY: Ministry of Electronics and Information Technology oversees India's digital and cyber policy", "Call for indigenous, resilient software and hardware to counter cyber threats", "Connects to India Semiconductor Mission (ISM) and Semicon India programme", "National Cyber Security Policy 2013 is being updated; CERT-In is the nodal agency for cyber incidents"], "source": "The Economic Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Vietnam Boat Tragedy: Mortal Remains of 15 Indian Tourists Repatriated to India", "category": "ir", "category_name": "International Relations", "summary": "The mortal remains of 15 Indian tourists killed in a speedboat accident near Phu Quoc island in Vietnam were repatriated to India, with bodies reaching Mumbai and Hyderabad. The tragedy occurred when a speedboat capsized, killing the Indian tourists. Indian consular officials coordinated the repatriation process. The incident raises questions about tourist safety regulations in Vietnam and India's consular response mechanisms.", "exam_angle": "Relevant for GS Paper 2 (IR) — India's consular services, diaspora protection, Ministry of External Affairs' role, and bilateral India-Vietnam relations.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["15 Indian tourists killed in speedboat accident near Phu Quoc island, Vietnam", "Mortal remains repatriated to India (Mumbai and Hyderabad)", "Indian consular officials coordinated repatriation", "India-Vietnam: Comprehensive Strategic Partnership (upgraded in 2016)"], "source": "The Times of India / India Today / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Europe Records Over 10,000 Excess Deaths During June 2026 Heatwave", "category": "environment", "category_name": "Environment & Ecology", "summary": "A report recorded over 10,000 excess deaths across Europe during the June 2026 heatwave, highlighting the growing health impact of climate change-driven extreme heat events. Excess deaths refer to deaths above the statistically expected baseline during the same period in normal years. The event underscores the urgency of heat action plans and adaptation strategies. The World Meteorological Organization (WMO) has repeatedly flagged Europe as one of the fastest-warming continents.", "exam_angle": "Relevant for GS Paper 3 (Environment) and GS Paper 1 (Geography) — climate change impacts, heat action plans, WMO reports, and urban heat island effect.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Over 10,000 excess deaths recorded in Europe during June 2026 heatwave", "'Excess deaths': deaths above statistically expected baseline", "WMO identifies Europe as one of the fastest-warming continents", "India has National Heat Action Plans (implemented by NDMA) as a parallel context"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Commerce Ministry to Lead Business Delegation to Spain, Belgium and Finland for Trade and Technology Ties", "category": "ir", "category_name": "International Relations", "summary": "The Union Minister of Commerce and Industry is set to lead an Indian business delegation to Spain, Belgium, and Finland to strengthen trade, investment, and technology linkages. The visit is part of India's broader engagement with European Union member states ahead of the India-EU Free Trade Agreement (FTA) negotiations. Belgium is home to major EU institutions, while Finland and Spain are significant trade and technology partners.", "exam_angle": "Relevant for GS Paper 2 (IR) — India-EU relations, FTA negotiations, and trade diplomacy; Belgium's importance as EU institutional hub is a useful fact.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Commerce Minister to lead delegation to Spain, Belgium, and Finland", "Objective: boost trade, investment, and technology ties", "Belgium hosts key EU institutions (European Commission, Council)", "India-EU FTA negotiations (Broad-based Trade and Investment Agreement) are ongoing"], "source": "Business Standard", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Sonam Wangchuk's Hunger Strike: Citizens for Justice and Peace Issues Open Letter", "category": "polity", "category_name": "Polity & Governance", "summary": "Citizens for Justice and Peace (CJP) issued an open letter in response to activist Sonam Wangchuk's ongoing hunger strike, demanding statehood and constitutional safeguards (Sixth Schedule protections) for Ladakh. Wangchuk, a Magsaysay Award-winning engineer and activist, has been demanding that Ladakh be granted full statehood or included in the Sixth Schedule of the Constitution to protect tribal land and resources. Ladakh has been a Union Territory (without legislature) since October 31, 2019, following the reorganisation of Jammu & Kashmir.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — Sixth Schedule, constitutional status of Ladakh, Article 370 reorganisation, and tribal rights under Fifth and Sixth Schedules.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Sonam Wangchuk: Magsaysay Award-winning activist from Ladakh", "Demands: statehood for Ladakh OR inclusion under Sixth Schedule of the Constitution", "Sixth Schedule: protects tribal autonomy in northeastern states; covers Assam, Meghalaya, Tripura, Mizoram", "Ladakh became a UT without legislature on October 31, 2019 (J&K Reorganisation Act, 2019)"], "source": "The Indian Express", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Vietnam Boat Tragedy: 15 Indian Tourists Killed Near Phu Quoc Island, Embassy Begins Repatriation", "category": "ir", "category_name": "International Relations", "summary": "At least 15 Indian tourists were killed when a speedboat capsized near Phu Quoc island off Vietnam's coast. Vietnam police arrested the boat's captain for violations of maritime law. The Indian Embassy in Vietnam initiated repatriation of mortal remains, while 16 survivors returned home with one hospitalised. The incident drew condolences from Indian political leaders including K. Annamalai.", "exam_angle": "Tests knowledge of India's consular responsibilities under the Vienna Convention on Consular Relations and India's bilateral ties with Vietnam. Also relevant to maritime safety and Indian diaspora protection.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Deaths: 15 Indian tourists killed near Phu Quoc island, Vietnam", "16 survivors returned to India; 1 hospitalised", "Vietnam police arrested the boat captain", "Indian Embassy initiated repatriation of mortal remains"], "source": "The Hindu / NDTV / Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "India Condemns Iranian Attack on MV GFS Galaxy in Strait of Hormuz; Indian Crew Member Missing", "category": "ir", "category_name": "International Relations", "summary": "India condemned the attack on the vessel GFS Galaxy off Oman's coast in the Strait of Hormuz amid the escalating US-Iran conflict. One Indian crew member was reported missing while 10 were rescued. Iran has threatened to close the Strait of Hormuz, a critical global oil transit chokepoint. The US struck 140 Iranian targets following the Hormuz closure, while Iran retaliated by striking UAE and Qatar.", "exam_angle": "Strait of Hormuz is critical for India's energy security — nearly 80% of India's crude oil imports pass through it. The conflict directly impacts Indian nationals, energy prices, and India's West Asia diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Vessel attacked: MV GFS Galaxy, off Oman's coast in Strait of Hormuz", "1 Indian crew member missing; 10 rescued", "US struck 140 Iranian targets after Hormuz closure", "Iran struck UAE and Qatar in retaliation; Strait of Hormuz carries ~20% of global oil trade"], "source": "Hindustan Times / NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "FPI Inflows Return to Indian Equities in July 2026 with Rs 15,157 Crore After Four-Month Selling Streak", "category": "economy", "category_name": "Economy & Banking", "summary": "Foreign Portfolio Investors (FPIs) reversed a four-month selling trend by infusing Rs 15,157 crore into Indian stock markets in July 2026. The return of FPI capital signals renewed confidence in India's economic fundamentals. The prolonged selling had been driven by global risk-off sentiment and geopolitical tensions. This inflow is significant for the stability of Indian financial markets and the rupee.", "exam_angle": "FPI flows are a key indicator of capital account dynamics, exchange rate management, and investor confidence. Relevant to RBI's balance of payments management and SEBI's regulatory framework for FPIs.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["FPI inflow in July 2026: Rs 15,157 crore", "Ended a 4-month consecutive selling streak", "FPIs invest in Indian markets under SEBI's FPI Regulations 2019", "FPI flows impact exchange rate, forex reserves, and capital account"], "source": "Moneycontrol", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "PM Modi Highlights New Zealand's Role in Chandrayaan-3 Success; India-NZ Partnership Elevated", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi, concluding his visit to New Zealand, acknowledged the New Zealand space sector's contribution to the success of India's Chandrayaan-3 mission. The visit led to an elevation of the India-New Zealand bilateral partnership. The Congress party also recalled former New Zealand PM's role in reviving India-NZ ties in the 1980s. The visit strengthens Indo-Pacific cooperation between the two nations.", "exam_angle": "Relevant to India's space diplomacy, ISRO's international collaborations, and India's Indo-Pacific engagement strategy. Chandrayaan-3 (August 2023) made India the first nation to land near the lunar south pole.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["PM Modi concluded visit to New Zealand", "India-NZ bilateral partnership elevated", "New Zealand space sector contributed to Chandrayaan-3 mission", "Chandrayaan-3 landed near lunar south pole on 23 August 2023"], "source": "NDTV / Akashvani News", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "J&K Statehood Controversy: Omar Abdullah Demands Restoration, Accuses BJP of 'Backdoor' Politics", "category": "polity", "category_name": "Polity & Governance", "summary": "Jammu & Kashmir Chief Minister Omar Abdullah publicly demanded restoration of statehood for J&K, raising the question of when the Centre plans to act on its repeated assurances. He alleged that the BJP was engaged in 'backdoor' politics, including alleged attempts to poach MLAs with offers. J&K was downgraded from a state to a Union Territory with legislature in October 2019 under the Jammu and Kashmir Reorganisation Act. The Supreme Court in 2023 directed restoration of statehood at the earliest.", "exam_angle": "Directly relevant to Polity — J&K's constitutional status under Article 3, the Reorganisation Act 2019, and the Supreme Court's October 2023 judgment in the Article 370 case which directed statehood restoration.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["J&K downgraded to UT in October 2019 under J&K Reorganisation Act 2019", "Supreme Court (Nov 2023) upheld abrogation of Article 370 and directed statehood restoration 'at the earliest'", "Omar Abdullah is current CM of J&K UT", "J&K UT has a legislature (Legislative Assembly), unlike Ladakh UT"], "source": "Times of India / NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Stakeholders Term PM/CM Removal Clause in One Nation One Election Bill 'Unconstitutional'", "category": "polity", "category_name": "Polity & Governance", "summary": "Stakeholders and constitutional experts have flagged a provision in the proposed One Nation One Election (ONOE) framework that deals with removal of the Prime Minister or Chief Ministers, calling it 'unconstitutional'. The clause has raised concerns about its compatibility with the basic structure doctrine and parliamentary democracy. The 129th Constitutional Amendment Bill underpins the ONOE proposal. The issue connects to debates on federalism and separation of powers.", "exam_angle": "Directly relevant to constitutional law, basic structure doctrine (Kesavananda Bharati case), and the ongoing ONOE legislative debate. Tests understanding of removal procedures under Articles 75 and 164.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["One Nation One Election proposed via 129th Constitutional Amendment Bill", "Contentious clause relates to removal of PM/CMs in mid-term scenarios", "Basic structure doctrine limits Parliament's power to amend the Constitution", "PM's removal governed by Article 75(3); CM's by Article 164(2) — both require floor test"], "source": "Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Andhra Pradesh on Alert After 2 COVID-19 Deaths and 8 Active Cases Reported", "category": "scitech", "category_name": "Science & Technology", "summary": "Andhra Pradesh health authorities have gone on alert after 2 COVID-19 deaths and 8 active cases were reported in the state. The development signals a need for continued surveillance even as global pandemic emergency status has been lifted. Health authorities are monitoring the situation for any new variants. The Union Health Ministry is also expected to review the situation.", "exam_angle": "Relevant to public health governance, disaster management (Epidemic Diseases Act / NDMA), and Centre-State health coordination. Also tests awareness of COVID-19 management frameworks in India.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["State: Andhra Pradesh; 2 COVID-19 deaths, 8 active cases reported", "WHO declared end of COVID-19 as a Public Health Emergency of International Concern (PHEIC) in May 2023", "India's epidemic management falls under Epidemic Diseases Act 1897 (amended 2020)", "National Disaster Management Act 2005 was invoked during COVID-19 pandemic"], "source": "NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Nepal Remains India's Largest Source of Foreign Students; Karnataka Emerges as Top Study Destination", "category": "reports", "category_name": "Reports & Indices", "summary": "According to data released by the Ministry of Education (MoE), Nepal continues to be the largest source of foreign students studying in India. Karnataka has emerged as the most preferred state destination among international students in India. The data underscores India's growing soft power in the education sector and its appeal as a study destination in South Asia. India has been actively promoting itself as an education hub under the National Education Policy 2020.", "exam_angle": "Relevant to India's soft power, education diplomacy, and NEP 2020 goals of internationalisation of Indian education. Also tests India-Nepal bilateral relations and cultural ties.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Source: Ministry of Education (MoE) data", "Nepal: largest source of foreign students in India", "Karnataka: top destination state for foreign students in India", "NEP 2020 targets India becoming a global study destination"], "source": "Times of India / Economic Times", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "E20 Ethanol-Blended Petrol Controversy: Fuel Efficiency Concerns Spark National Debate", "category": "economy", "category_name": "Economy & Banking", "summary": "India's push for E20 fuel (20% ethanol blended with 80% petrol) has sparked public controversy after complaints about reduced vehicle fuel efficiency emerged virally on social media. The government's Ethanol Blending Programme (EBP) aims to achieve 20% blending by 2025 to reduce oil imports, support farmers, and cut carbon emissions. Critics argue older vehicles are not E20-compatible, leading to mileage drops. The Ministry of Petroleum and Natural Gas oversees the EBP.", "exam_angle": "Relevant to India's energy security, the Ethanol Blending Programme under National Biofuel Policy 2018 (amended 2022), and the government's target of reducing crude oil import dependency.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20 = 20% ethanol + 80% petrol blend", "India's Ethanol Blending Programme (EBP) target: 20% blending by 2025-26", "Policy governed by National Biofuel Policy 2018 (amended 2022)", "Nodal ministry: Ministry of Petroleum and Natural Gas"], "source": "Hindustan Times / News18 / Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Bangladesh Terror Probe Links Martial Arts Organisation 'Fatah Combat System' to Extremist Networks", "category": "ir", "category_name": "International Relations", "summary": "A terror investigation in Bangladesh has exposed links between a martial arts organisation called 'Fatah Combat System' and extremist networks, with a student leader also implicated. Seven persons were remanded by Bangladeshi courts over alleged extremism connections. The probe reveals the evolving nature of terrorist recruitment and radicalisation through non-traditional organisations in India's neighbourhood. India closely monitors extremism developments in Bangladesh given cross-border security implications.", "exam_angle": "Relevant to India's neighbourhood policy, counter-terrorism cooperation under SAARC/bilateral frameworks, and internal security threats emanating from Bangladesh's territory. Bangladesh is a key partner in India's 'Neighbourhood First' policy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Organisation under probe: Fatah Combat System (martial arts group)", "7 persons remanded over alleged extremist links", "Country: Bangladesh", "Relevant to India-Bangladesh security cooperation and counter-terrorism"], "source": "NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Typhoon Bavi Batters Eastern China, Nearly Two Million Evacuated", "category": "environment", "category_name": "Environment & Ecology", "summary": "Typhoon Bavi made landfall in eastern China, prompting the evacuation of nearly two million people. China activated emergency response mechanisms as the typhoon brought heavy rainfall and strong winds. Typhoons in the Western Pacific are the equivalent of hurricanes/cyclones and frequently impact China's eastern coastal provinces. The event highlights the increasing frequency and intensity of extreme weather events linked to climate change.", "exam_angle": "Relevant to disaster management, climate change impacts, and cyclone/typhoon geography for GS Paper 1 (Geography) and GS Paper 3 (Disaster Management). Typhoons form in the North-Western Pacific Ocean.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["Typhoon Bavi made landfall in eastern China", "Nearly 2 million people evacuated", "Typhoons = tropical cyclones of the Western Pacific/South China Sea", "China activated national emergency response protocol"], "source": "Reuters / BBC", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Ebola Treatment Trial Begins in DRC: First Patients Enrolled in Record-Breaking Study", "category": "scitech", "category_name": "Science & Technology", "summary": "The first patients have been enrolled in a record-breaking Ebola virus disease treatment clinical trial in the Democratic Republic of Congo (DRC). The trial aims to test new therapeutic interventions against Ebola, which has caused multiple deadly outbreaks in Central Africa. DRC has been the epicentre of most Ebola outbreaks globally. The WHO and international health organisations are supporting the trial.", "exam_angle": "Relevant to global health governance, WHO's role in disease outbreaks, and India's engagement with global health security frameworks. Ebola is a zoonotic disease classified as a Risk Group 4 pathogen.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Disease: Ebola Virus Disease (EVD)", "Location of trial: Democratic Republic of Congo (DRC)", "DRC is the most affected country historically by Ebola outbreaks", "Ebola is caused by Ebola virus (Filoviridae family); zoonotic origin"], "source": "The Guardian", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Former Qatar Emir Sheikh Hamad bin Khalifa Al Thani Dies at 74", "category": "persons", "category_name": "Persons & Awards in News", "summary": "Sheikh Hamad bin Khalifa Al Thani, the former Emir of Qatar who ruled from 1995 to 2013, passed away at the age of 74. He was credited with transforming Qatar into a major global player through the establishment of Al Jazeera, hosting the 2022 FIFA World Cup bid, and expanding Qatar's LNG exports. He voluntarily abdicated in 2013 in favour of his son, Sheikh Tamim bin Hamad Al Thani. Qatar is a critical partner in global energy markets and West Asia diplomacy.", "exam_angle": "Relevant to West Asia geopolitics, India's energy security (Qatar is a major LNG supplier to India), and India-Qatar bilateral relations. Qatar currently hosts one of India's largest diaspora populations in the Gulf.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Deceased: Sheikh Hamad bin Khalifa Al Thani, former Emir of Qatar", "Ruled Qatar: 1995–2013; abdicated in favour of son Sheikh Tamim", "Founded Al Jazeera media network", "Qatar is India's largest supplier of LNG (Liquefied Natural Gas)"], "source": "NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Singer S. Janaki, 'Nightingale of South India', Passes Away at 88", "category": "persons", "category_name": "Persons & Awards in News", "summary": "Legendary playback singer S. Janaki, widely known as the 'Nightingale of South India', passed away at the age of 88 in Mysuru due to age-related ailments. She was one of the most prolific and celebrated voices in Indian cinema, having sung in multiple South Indian languages including Kannada, Tamil, Telugu, and Malayalam over six decades. She received numerous national and state awards during her lifetime. Prominent personalities including Rajinikanth, CM Vijay, and Kamal Haasan paid tributes.", "exam_angle": "Relevant to GS Paper 1 (Indian Art & Culture) — persons in news category. Tests awareness of India's cultural heritage in music and the classical/film music tradition of South India.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Name: S. Janaki (Sithara Janaki); known as 'Nightingale of South India'", "Passed away at age 88 in Mysuru", "Sang in Kannada, Tamil, Telugu, Malayalam, and other languages", "Recipient of multiple National Film Awards and Padma awards"], "source": "Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "India Heritage Centre Plans Washington D.C. Museum to Showcase India's Civilisational Journey", "category": "culture", "category_name": "Art & Culture", "summary": "The India Heritage Centre has announced plans to establish a museum in Washington D.C. dedicated to showcasing India's civilisational and cultural journey. The proposed museum aims to strengthen India's soft power and cultural diplomacy in the United States. It is intended to present India's history, art, science, and philosophy to a global audience. The initiative aligns with India's broader cultural outreach under the Ministry of Culture and ICCR.", "exam_angle": "Relevant to India's soft power, cultural diplomacy, and the role of the Indian Council for Cultural Relations (ICCR). Connects to GS Paper 1 (Culture) and GS Paper 2 (India-US relations).", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Organisation: India Heritage Centre", "Planned location: Washington D.C., USA", "Purpose: Museum showcasing India's civilisational journey", "Aligns with India's soft power and cultural diplomacy objectives"], "source": "India Today", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "PE Investments in India Reach $8.7 Billion in H1 2026", "category": "economy", "category_name": "Economy & Banking", "summary": "Private Equity (PE) investments in India clocked $8.7 billion in the first half of 2026 (January–June), reflecting sustained investor confidence in the Indian economy. PE investments are a key source of growth capital for Indian startups and mid-sized companies. The strong inflows come despite global economic uncertainties arising from the US-Iran conflict and trade tensions. India remains one of the most attractive PE destinations in Asia.", "exam_angle": "Relevant to capital markets, foreign investment framework (FEMA), and India's position as an investment destination. PE investments are regulated through SEBI's AIF (Alternative Investment Fund) regulations.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["PE investment in India H1 2026: $8.7 billion", "PE funds in India regulated under SEBI's AIF Regulations 2012", "PE investments are Category II AIFs under SEBI framework", "India ranks among top 3 PE destinations in Asia-Pacific"], "source": "Business Standard", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Canada-India CEPA Negotiations: Trade Minister to Lead Business Delegation in October 2026", "category": "ir", "category_name": "International Relations", "summary": "Canada's Trade Minister is set to lead a business delegation to India in October 2026 as negotiations for a Comprehensive Economic Partnership Agreement (CEPA) advance. The CEPA intends to provide preferential market access to Indian goods and services in Canada. India-Canada trade relations have been strained following the diplomatic row over the Nijjar killing case in 2023. A CEPA would be significant for sectors like pharmaceuticals, IT, and agri-products.", "exam_angle": "Relevant to India's trade policy, bilateral FTA/CEPA negotiations, and India-Canada diplomatic relations. Tests understanding of CEPA vs FTA frameworks and India's trade negotiation strategy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Agreement type: CEPA (Comprehensive Economic Partnership Agreement)", "Parties: India and Canada", "Canadian Trade Minister to visit India with business delegation in October 2026", "India-Canada relations strained since 2023 Nijjar diplomatic row"], "source": "The Indian Express", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Sonam Wangchuk's Fast Enters 15th Day Over Ladakh's Sixth Schedule Demand", "category": "polity", "category_name": "Polity & Governance", "summary": "Climate activist and innovator Sonam Wangchuk's hunger strike demanding constitutional safeguards for Ladakh entered its 15th day, with his health reported to be worsening. Wangchuk and the Leh Apex Body are demanding inclusion of Ladakh under the Sixth Schedule of the Constitution, which would provide autonomous district councils to protect tribal rights and land. Ladakh was carved out as a separate Union Territory without a legislature in October 2019. The Centre has not formally agreed to the Sixth Schedule demand.", "exam_angle": "Directly relevant to the Sixth Schedule of the Constitution (tribal autonomy in North-East and now demanded for Ladakh), UT governance without legislature, and the political situation post-abrogation of Article 370.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Activist: Sonam Wangchuk (also known for SECMOL and ice stupa innovation)", "Demand: Inclusion of Ladakh under Sixth Schedule of the Constitution", "Sixth Schedule currently applies to tribal areas of Assam, Meghalaya, Tripura, Mizoram", "Ladakh became UT without legislature under J&K Reorganisation Act 2019"], "source": "India Today / The Hindu", "day": "2026-07-12", "day_label": "12 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "reports", "name": "Reports & Indices"}, {"id": "persons", "name": "Persons & Awards in News"}, {"id": "culture", "name": "Art & Culture"}]};